function rowWeek(p,r,w){const team=String(r?.team||p.team||'').toUpperCase(),opp=opponent(team,w),bye=opp==='BYE',cur=Number(w)===Number(bundle?.week||window.currentWeek?.()||1),published=cur?null:num(window.FIESpecialTeamsSeries?.sleeperProjection?.(p,w,season())),base=cur?currentProjection(p,r):(published??currentProjection(p,r)),rg=currentRange(p,r),mean=bye?0:base,low=bye?0:(published!==null?Math.max(0,published*.78):rg.low),high=bye?0:(published!==null?published*1.22:rg.high),source=bye?'Schedule':cur?(r?.projection_source||'Current-week baseline'):published!==null?`Sleeper Week ${w}`:'Baseline Estimate',estimate=!bye&&!cur;return{p,r,id:String(p.sleeperId||p.name),name:p.name||r?.full_name||'Kicker',team:team||'—',opp,mean,low,high,status:owner(p),active:cur&&r?.weekly_activation_eligible===true,source,estimate,bye,week:w};}
function boardForWeek(w=week()){const m=cmap(),xs=players().map(p=>rowWeek(p,m.get(String(p.sleeperId||''))||null,w)).filter(x=>x.mean!==null);xs.sort((a,b)=>b.mean-a.mean);xs.forEach((x,i)=>x.rank=i+1);return xs;}
function replacement(xs){const svc=window.FIECore?.ReplacementService;if(svc?.row){const z=svc.row('K',xs.map(x=>({p:x.p,score:x.mean,mean:x.mean})),'score',{league:state.league,state});if(z?.row)return xs.find(x=>x.p===z.row.p)||null;}const teams=Number(state.league?.total_rosters||state.rosters?.length||12),slots=(state.league?.roster_positions||[]).filter(x=>String(x).toUpperCase()==='K').length||1;return xs[Math.min(xs.length-1,Math.max(0,teams*slots-1))]||null;}
function next3(x){if(!x)return null;const vals=[];for(let w=x.week;w<=Math.min(18,x.week+2);w++){const z=boardForWeek(w).find(y=>y.id===x.id);if(z?.mean!==null)vals.push(z.mean);}return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;}
function strategy(xs){if(!xs.length)return null;const repl=replacement(xs),best=xs[0],fas=xs.filter(x=>x.status==='FA'),faTop=fas[0],teams=Math.max(1,Number(state.league?.total_rosters||state.rosters?.length||12)),hold=best.mean-(repl?.mean??best.mean),stream=(faTop?.mean??repl?.mean??best.mean)-(repl?.mean??best.mean),depth=fas.length/teams,scarcity=Math.max(0,Math.min(100,(teams/Math.max(1,xs.length))*100+(1-Math.min(1,depth))*35));let verdict='STREAM',why='Free-agent quality is close enough to replacement that draft capital is better spent elsewhere.';if(hold>=1.5&&scarcity>=55){verdict='PAY';why='Top-kicker edge is meaningful and the league-specific replacement pool is thin.';}else if(hold>=.8||depth<.7){verdict='WAIT';why='There is some hold value, but not enough separation to justify an early premium.';}return{repl,best,faTop,hold,stream,depth,scarcity,verdict,why};}
